<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\DB;
use App\Services\Planner;
class PlannerTest extends TestCase {
 use RefreshDatabase;
 private function plan():array{return json_decode(file_get_contents(base_path('../examples/rani-plan.json')),true);}
 private function signIn():static{return $this->withSession(['planner_authenticated'=>true]);}
 private function import():void{$this->signIn()->postJson('/api/imports',['document'=>$this->plan(),'confirm_replace'=>true])->assertCreated();}
 public function test_authentication_is_required():void{$this->getJson('/api/state')->assertUnauthorized();}
 public function test_example_imports_exact_partial_and_full_weeks():void{$this->import();$this->assertDatabaseCount('priorities',8);$this->assertDatabaseCount('template_blocks',15);$this->assertDatabaseCount('work_blocks',23);$this->assertEquals(1440,DB::table('work_blocks')->whereBetween('date',['2026-11-02','2026-11-08'])->sum('duration_minutes'));}
 public function test_invalid_reference_does_not_delete_anything():void{$this->import();$d=$this->plan();$d['weeks'][0]['blocks'][0]['priority_id']='missing';$this->postJson('/api/imports',['document'=>$d,'confirm_replace'=>true])->assertUnprocessable();$this->assertDatabaseCount('work_blocks',23);$this->assertDatabaseCount('plan_imports',1);}
 public function test_duplicate_position_and_wrong_week_are_rejected():void{$this->signIn();$d=$this->plan();$d['weeks'][0]['blocks'][]=$d['weeks'][0]['blocks'][0];$this->postJson('/api/imports/preview',['document'=>$d])->assertUnprocessable();$d=$this->plan();$d['weeks'][0]['blocks'][0]['date']='2026-11-10';$this->postJson('/api/imports/preview',['document'=>$d])->assertUnprocessable();}
 public function test_reset_keeps_completed_snapshot_and_removes_unfinished_work():void{$this->import();$b=DB::table('work_blocks')->first();$this->postJson('/api/blocks/'.$b->id.'/completion',['revision'=>1,'completed'=>true])->assertNoContent();$d=$this->plan();$d['weeks']=[];$d['priorities'][0]['name']='New name';$this->postJson('/api/imports',['document'=>$d,'confirm_replace'=>true])->assertCreated();$this->assertDatabaseCount('work_blocks',1);$kept=DB::table('work_blocks')->first();$this->assertEquals($b->priority_name,$kept->priority_name);$this->assertNull($kept->priority_id);}
 public function test_moves_and_partial_splits_preserve_minutes_and_origin():void{$this->import();$b=DB::table('work_blocks')->first();$total=DB::table('work_blocks')->sum('duration_minutes');$this->patchJson('/api/blocks/'.$b->id,['revision'=>1,'date'=>'2026-11-07','slot'=>'extra'])->assertNoContent();$this->postJson('/api/blocks/'.$b->id.'/split',['revision'=>2,'first_minutes'=>90,'date'=>null,'slot'=>'extra','complete_first'=>true])->assertNoContent();$this->assertEquals($total,DB::table('work_blocks')->sum('duration_minutes'));$parts=DB::table('work_blocks')->where('origin_id',$b->origin_id)->get();$this->assertCount(2,$parts);$this->assertEquals(90,$parts->where('completed',true)->sum('duration_minutes'));$this->assertEquals(90,$parts->whereNull('date')->sum('duration_minutes'));$this->assertDatabaseCount('template_blocks',15);}
 public function test_stale_edits_are_rejected():void{$this->import();$b=DB::table('work_blocks')->first();$d=['revision'=>1,'date'=>null,'slot'=>'extra'];$this->patchJson('/api/blocks/'.$b->id,$d)->assertNoContent();$this->patchJson('/api/blocks/'.$b->id,$d)->assertConflict();}
 public function test_invalid_split_does_not_change_hours():void{$this->import();$b=DB::table('work_blocks')->first();$this->postJson('/api/blocks/'.$b->id.'/split',['revision'=>1,'first_minutes'=>180,'date'=>null,'slot'=>'extra'])->assertUnprocessable();$this->assertDatabaseCount('work_blocks',23);}
 public function test_restore_recovers_state_before_destructive_import():void{$this->import();$d=$this->plan();$d['weeks']=[];$r=$this->postJson('/api/imports',['document'=>$d,'confirm_replace'=>true])->assertCreated();$this->assertDatabaseCount('work_blocks',0);$this->postJson('/api/imports/'.$r->json('id').'/restore',['confirm_restore'=>true])->assertNoContent();$this->assertDatabaseCount('work_blocks',23);}
 public function test_import_rolls_back_when_a_database_write_fails():void{$this->import();DB::statement("CREATE TRIGGER reject_priority BEFORE INSERT ON priorities BEGIN SELECT RAISE(ABORT, 'simulated failure'); END");$this->postJson('/api/imports',['document'=>$this->plan(),'confirm_replace'=>true])->assertStatus(500);$this->assertDatabaseCount('work_blocks',23);$this->assertDatabaseCount('priorities',8);$this->assertDatabaseCount('plan_imports',1);}
 public function test_generating_a_week_is_explicit_and_idempotent():void{$this->import();$this->postJson('/api/weeks',['week_start'=>'2026-11-16'])->assertNoContent();$this->assertDatabaseCount('work_blocks',38);$this->postJson('/api/weeks',['week_start'=>'2026-11-16'])->assertConflict();$this->assertDatabaseCount('work_blocks',38);}
}
